// JAH demo program - run with: node demo.js (or paste into a browser console)
// Demo: Algorithm Generator - public implementations survey
(function(){'use strict';
var DATA={"label": "Algorithm Generator - public implementations survey", "arr": [18, 23, 64, 80, 129, 152, 170, 173, 180, 196], "target": 173};

var a=DATA.arr,t=DATA.target,lo=0,hi=a.length-1,steps=0;
console.log('Binary search for '+t+' in ['+a.join(', ')+'] ('+DATA.label+'):');
while(lo<=hi){var mid=(lo+hi)>>1;steps++;
  console.log('  step '+steps+': mid='+mid+' value='+a[mid]);
  if(a[mid]===t){console.log('FOUND at index '+mid+' in '+steps+' steps');break;}
  else if(a[mid]<t)lo=mid+1;else hi=mid-1;}
if(lo>hi)console.log('NOT FOUND after '+steps+' steps');
})();

// JAH demo program - run with: node demo.js (or paste into a browser console)
// Demo: Bloom filters - related Algorithm Generator technology
(function(){'use strict';
var DATA={"label": "Bloom filters - related Algorithm Generator technology", "arr": [64, 32, 4, 70, 32, 62, 16, 48]};

var a=DATA.arr.slice(),cmp=0,sw=0;
function qs(lo,hi){if(lo>=hi)return;var piv=a[hi],i=lo;
  for(var j=lo;j<hi;j++){cmp++;if(a[j]<piv){var t=a[i];a[i]=a[j];a[j]=t;i++;sw++;}}
  var t2=a[i];a[i]=a[hi];a[hi]=t2;sw++;qs(lo,i-1);qs(i+1,hi);}
console.log('Quicksort ('+DATA.label+'): input ['+DATA.arr.join(', ')+']');
qs(0,a.length-1);
console.log('sorted: ['+a.join(', ')+']');
console.log('comparisons='+cmp+' swaps='+sw);
})();

